def admit_config(path, pin, fmt, used, extra=None):
    """Shared c2v004 admission (schema V004 = the c2v003 rules + declared alternative members). The config {format,schema{name,path,sha256},
 galaxy,fields[,extra]} is pinned by sha256, refers to the pinned schema V003 and names a galaxy with a schema entry.
 A USED field is admitted only if present with a whitelisted status, or DERIVED_FROM_BYTES_CONDITIONAL equal to the
 schema entry with a structured condition {field,equals} naming an admitted field that holds exactly that value.
 DDO154 configs: only DDO154_EXACT_LITERAL (== schema ddo154 value) or PER_CALL. PER_CALL only on a per-call kind, a
 call input, or a field whose schema entry for this galaxy is a DECLARED_INPUT_SLOT. Any other admitted status must be
 the schema entry's own status with the schema entry's own value. No value may hold a sentinel at any depth. extra maps
 each further top-level key to a check returning a refusal or None. Every refusal is listed together; nothing is
 guessed. c2v004: an optional top-level 'member' must name a declared alternative member of the galaxy (MEMBER_ENTRY,
 equal to the schema 'members' entry); every field is then checked against that member's entry instead of the galaxy
 entry. Without member every rule is the c2v003 rule. Returns (galaxy, {field: value} for used, config)."""
    if not _hex64(pin):
        raise GalaxyConfigRefused('Galaxy config sha256 must be 64 lowercase hexadecimal characters')
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != pin:
        raise GalaxyConfigRefused('Pin mismatch: ' + str(path))
    sraw = SCHEMA[0].read_bytes()
    if hashlib.sha256(sraw).hexdigest() != SCHEMA[1]:
        raise GalaxyConfigRefused('Pin mismatch: ' + str(SCHEMA[0]))
    cfg = json.loads(raw)
    schema = json.loads(sraw)
    sf = {f['field']: f for f in schema['fields']}
    extra = extra or {}
    if schema.get('schema') != SCHEMA_NAME or len(sf) != len(schema['fields']):
        raise GalaxyConfigRefused('Galaxy config schema identity')
    if type(cfg) is not dict or set(cfg) - {'member'} != {'format', 'schema', 'galaxy', 'fields'} | set(extra) or cfg['format'] != fmt or (cfg['schema'] != {'name': SCHEMA_NAME, 'path': str(SCHEMA[0]), 'sha256': SCHEMA[1]}) or (type(cfg['fields']) is not dict) or (not set(cfg['fields']) <= set(sf)) or (type(cfg['galaxy']) is not str) or (not cfg['galaxy']):
        raise GalaxyConfigRefused('Galaxy config must be a ' + fmt + ' instance of ' + SCHEMA_NAME + ' with keys format/schema/galaxy/fields[/member]' + ''.join(('/' + k for k in sorted(extra))))
    if cfg['galaxy'] not in GALAXY_ENTRY:
        raise GalaxyConfigRefused('GALAXY_NOT_IN_SCHEMA: ' + repr(cfg['galaxy']))
    if 'member' in cfg and (type(cfg['member']) is not str or (cfg['galaxy'], cfg['member']) not in MEMBER_ENTRY):
        raise GalaxyConfigRefused('MEMBER_NOT_IN_SCHEMA: ' + repr((cfg['galaxy'], cfg['member'])))
    if 'member' in cfg and (schema.get('members') or {}).get(cfg['galaxy'], {}).get(cfg['member'], {}).get('entry') != MEMBER_ENTRY[cfg['galaxy'], cfg['member']]:
        raise GalaxyConfigRefused('MEMBER_NOT_DECLARED_BY_SCHEMA: ' + repr(cfg['member']))
    F = cfg['fields']
    galaxy = cfg['galaxy']
    ent = MEMBER_ENTRY[galaxy, cfg['member']] if 'member' in cfg else GALAXY_ENTRY[galaxy]
    for n, e in F.items():
        if type(e) is not dict or 'value' not in e or type(e.get('status')) is not str or (not set(e) <= {'value', 'status', 'condition'}):
            raise GalaxyConfigRefused('Galaxy config field entry {value,status[,condition]} required: ' + n)

    def refusal(n, seen=()):
        if n not in F:
            return n + ' (MISSING)'
        e = F[n]
        st = e['status']
        se = sf[n][ent]
        if st == CONDITIONAL_STATUS:
            c = e.get('condition')
            if type(c) is not dict or set(c) != {'field', 'equals'} or c['field'] in seen + (n,):
                return n + ' (' + st + ' without a resolvable condition)'
            if galaxy == 'DDO154' or se.get('status') != st or _canon(se.get('condition')) != _canon(c) or (_canon(se.get('value')) != _canon(e['value'])):
                return n + ' (' + st + ' differs from the schema ' + ent + ' entry)'
            r = refusal(c['field'], seen + (n,))
            if r:
                return n + ' (conditional on ' + r + ')'
            if _canon(F[c['field']]['value']) != _canon(c['equals']):
                return n + ' (condition %s==%s not met)' % (c['field'], _canon(c['equals']))
        elif st == SLOT_STATUS:
            return n + ' (' + st + ' not filled: ' + str(e['value']) + ')'
        elif st not in ADMITTED_STATUS:
            return n + ' (' + st + ')'
        elif st == 'DDO154_EXACT_LITERAL':
            if galaxy != 'DDO154' or _canon(e['value']) != _canon(sf[n]['ddo154']['value']):
                return n + ' (status DDO154_EXACT_LITERAL but not the DDO154 literal)'
        elif st == 'PER_CALL':
            if sf[n]['kind'] not in PER_CALL_KINDS and n not in CALL_INPUT_FIELDS and (se.get('status') != SLOT_STATUS):
                return n + ' (PER_CALL status on a ' + sf[n]['kind'] + ' field)'
        elif galaxy == 'DDO154':
            return n + ' (status ' + st + ' on DDO154: only DDO154_EXACT_LITERAL or PER_CALL)'
        elif st != se.get('status') or _canon(e['value']) != _canon(se.get('value')):
            return n + ' (status/value differ from the schema ' + ent + ' entry)'
        s = _sentinel(e['value'])
        if s:
            return n + ' (' + s + ' value)'
        return None
    refused = [r for r in (refusal(n) for n in used) if r] + [k + ': ' + r for k, r in ((k, f(cfg[k])) for k, f in sorted(extra.items())) if r]
    if refused:
        raise GalaxyConfigRefused('GALAXY_CONFIG_REFUSED galaxy=%s; nothing guessed: %s' % (galaxy, '; '.join(refused)))
    if 'galaxy.key' in used and F['galaxy.key']['value'] != galaxy:
        raise GalaxyConfigRefused('Galaxy config galaxy.key differs from config galaxy')
    return (galaxy, {n: F[n]['value'] for n in used}, cfg)

