    extra = extra or {}
    if schema.get('schema') != SCHEMA_NAME or len(sf) != len(schema['fields']):
        raise GalaxyConfigRefused('Galaxy config schema identity')
    if type(cfg) is not dict or set(cfg) - {'member'} != {'format', 'schema', 'galaxy', 'fields'} | set(extra) or cfg['format'] != fmt or (cfg['schema'] != {'name': SCHEMA_NAME, 'path': str(SCHEMA[0]), 'sha256': SCHEMA[1]}) or (type(cfg['fields']) is not dict) or (not set(cfg['fields']) <= set(sf)) or (type(cfg['galaxy']) is not str) or (not cfg['galaxy']):
        raise GalaxyConfigRefused('Galaxy config must be a ' + fmt + ' instance of ' + SCHEMA_NAME + ' with keys format/schema/galaxy/fields[/member]' + ''.join(('/' + k for k in sorted(extra))))
    if cfg['galaxy'] not in GALAXY_ENTRY:
        raise GalaxyConfigRefused('GALAXY_NOT_IN_SCHEMA: ' + repr(cfg['galaxy']))
    if 'member' in cfg and (type(cfg['member']) is not str or (cfg['galaxy'], cfg['member']) not in MEMBER_ENTRY):
        raise GalaxyConfigRefused('MEMBER_NOT_IN_SCHEMA: ' + repr((cfg['galaxy'], cfg['member'])))
    if 'member' in cfg and (schema.get('members') or {}).get(cfg['galaxy'], {}).get(cfg['member'], {}).get('entry') != MEMBER_ENTRY[cfg['galaxy'], cfg['member']]:
        raise GalaxyConfigRefused('MEMBER_NOT_DECLARED_BY_SCHEMA: ' + repr(cfg['member']))
    F = cfg['fields']
    galaxy = cfg['galaxy']
    ent = MEMBER_ENTRY[galaxy, cfg['member']] if 'member' in cfg else GALAXY_ENTRY[galaxy]
    for n, e in F.items():
        if type(e) is not dict or 'value' not in e or type(e.get('status')) is not str or (not set(e) <= {'value', 'status', 'condition'}):
